package sp.phone.linuxdo;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The exact ten reaction images currently exposed by LINUX DO.
 *
 * <p>These tiny PNGs are embedded deliberately.  The reaction picker must remain complete and
 * visually identical when the CDN is blocked, and the post summary must not briefly fall back to
 * letters for site-specific emoji while a network request is in flight.</p>
 */
public final class LinuxDoReactionAssets {

    private static final List<String> IDS = Collections.unmodifiableList(Arrays.asList(
            "heart", "+1", "laughing", "open_mouth", "clap",
            "confetti_ball", "hugs", "distorted_face", "tieba_087", "bili_057"));
    private static final Map<String, byte[]> DECODED = new ConcurrentHashMap<>();
    private static final Map<String, String> DATA_URIS = new ConcurrentHashMap<>();

    private LinuxDoReactionAssets() {
    }

    public static List<String> ids() {
        return new ArrayList<>(IDS);
    }

    public static boolean contains(String reactionId) {
        return reactionId != null && IDS.contains(reactionId.trim());
    }

    public static byte[] bytesFor(String reactionId) {
        String id = reactionId == null ? "" : reactionId.trim();
        if (!IDS.contains(id)) return null;
        byte[] cached = DECODED.get(id);
        if (cached != null) return cached;
        String encoded = encodedFor(id);
        if (encoded == null) return null;
        byte[] decoded = Base64.getDecoder().decode(encoded);
        DECODED.put(id, decoded);
        return decoded;
    }

    /** Offline URL used by article HTML so custom emoji never touches the CDN. */
    public static String dataUriFor(String reactionId) {
        String id = reactionId == null ? "" : reactionId.trim();
        if (!IDS.contains(id)) return null;
        String cached = DATA_URIS.get(id);
        if (cached != null) return cached;
        byte[] bytes = bytesFor(id);
        if (bytes == null || bytes.length == 0) return null;
        String value = "data:image/png;base64,"
                + Base64.getEncoder().encodeToString(bytes);
        DATA_URIS.put(id, value);
        return value;
    }

    private static String encodedFor(String id) {
        switch (id) {
            case "heart":
                return "";
            case "+1":
                return "";
            case "laughing":
                return "";
            case "open_mouth":
                return "";
            case "clap":
                return "";
            case "confetti_ball":
                return "";
            case "hugs":
                return "";
            case "distorted_face":
                return "";
            case "tieba_087":
                return "";
            case "bili_057":
                return "";
            default:
                return null;
        }
    }
}
